import { DomainError } from "./errors";

export class Product {
  private available: number;
  private reserved = 0;

  constructor(
    readonly id: string,
    readonly name: string,
    initialStock: number,
  ) {
    if (!Number.isInteger(initialStock) || initialStock < 0) {
      throw new DomainError("invalid", "stock must be a non-negative integer");
    }
    this.available = initialStock;
  }

  get availableStock(): number {
    return this.available;
  }

  get reservedStock(): number {
    return this.reserved;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.available;
  }

  reserve(quantity: number): void {
    if (!this.canReserve(quantity)) {
      throw new DomainError("insufficient_stock", `insufficient stock for product ${this.id}`);
    }
    this.available -= quantity;
    this.reserved += quantity;
  }

  release(quantity: number): void {
    const q = Math.min(quantity, this.reserved);
    this.reserved -= q;
    this.available += q;
  }

  /** Reserved stock leaves the warehouse when the order ships. */
  consumeReserved(quantity: number): void {
    this.reserved = Math.max(0, this.reserved - quantity);
  }
}

